verus! {

    /// Pure specification of primality for a 64‐bit unsigned integer.
    /// We say `n` is prime iff `n ≥ 2` and no integer `k` in the range [2, n) divides `n`.
    spec fn is_prime(n: u64) -> bool {
        n >= 2
        &&
        forall |k: u64|
            2 <= k && k < n
            ==> n % k != 0
    }

    /// Implementation by testing all potential divisors in [2, n).
    fn prime_num(n: u64) -> bool
        requires n >= 2
        ensures  result == is_prime(n)
    {
        let mut i: u64 = 2;
        while i < n
            invariant  2 <= i && i <= n
            invariant  // so far, no divisor has been found
                        forall |k: u64|
                            2 <= k && k < i
                            ==> n % k != 0
            decreases  n - i
        {
            // Make the "no divisor so far" fact available
            assert(forall |k: u64| 2 <= k && k < i ==> n % k != 0);

            if n % i == 0 {
                // We found a divisor in [2, n), so n is definitely not prime
                assert(!is_prime(n));
                return false;
            }
            i += 1;
        }

        // If we exit the loop without finding any divisor, n is prime
        assert(is_prime(n));
        return true;
    }

}